using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Xml.Linq;
using System.IO.Compression;
using System.Collections.Generic;
using System.Net;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using kok;
class TranslationWorkspaceTests {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static string Read(ZipArchive zip,string name){using(var reader=new StreamReader(zip.GetEntry(name).Open()))return reader.ReadToEnd();}
 static void Write(ZipArchive zip,string name,string text){using(var writer=new StreamWriter(zip.CreateEntry(name).Open(),new UTF8Encoding(false)))writer.Write(text);}
 sealed class TranslateHandler:HttpMessageHandler {
  public int calls,active,maximum;public bool badTags;
  protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){Interlocked.Increment(ref calls);int count=Interlocked.Increment(ref active);maximum=Math.Max(maximum,count);try{await Task.Delay(100,token);var body=(Dictionary<string,object>)Library.Json.DeserializeObject(await request.Content.ReadAsStringAsync());var messages=(object[])body["messages"];var input=(object[])Library.Json.DeserializeObject(Convert.ToString(((Dictionary<string,object>)messages[1])["content"]));var rows=input.Cast<Dictionary<string,object>>().Reverse().Select(row=>new{id=row["id"],text=badTags?"broken":"译文："+row["text"]}).ToArray();return new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(Library.Json.Serialize(new{choices=new[]{new{finish_reason="stop",message=new{content=Library.Json.Serialize(new{translations=rows})}}}}),Encoding.UTF8,"application/json")};}finally{Interlocked.Decrement(ref active);}}
 }
 sealed class SpeechHandler:HttpMessageHandler {
  public int calls;public bool safe;
  protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){calls++;var content=await request.Content.ReadAsByteArrayAsync();string body=Encoding.UTF8.GetString(content);safe=request.RequestUri.AbsolutePath=="/v1/audio/transcriptions"&&request.Headers.Authorization.Parameter=="dummy-asr-credential"&&body.Contains("RIFF")&&body.Contains("verbose_json")&&!body.Contains("chat-credential");return new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent("{\"segments\":[{\"start\":0.2,\"end\":1.8,\"text\":\"字幕内容\"},{\"start\":2.0,\"end\":3.0,\"text\":\"第二句\"}]}")};}
 }
 static string TranslateMarkup(string value){return System.Text.RegularExpressions.Regex.Replace(value,@"(<kok-r-\d+>)(.*?)(</kok-r-\d+>)",m=>m.Groups[1].Value+"译文 "+m.Groups[2].Value+m.Groups[3].Value,System.Text.RegularExpressions.RegexOptions.Singleline);}
 static void Main(string[] args){try{Run(args).GetAwaiter().GetResult();}catch(Exception error){Console.Error.WriteLine(error);Environment.ExitCode=1;}}
 static async Task Run(string[] args){string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);XNamespace w="http://schemas.openxmlformats.org/wordprocessingml/2006/main";
  foreach(string format in new[]{"docx","epub"}){
   string file=Path.Combine(root,"source."+format);File.WriteAllBytes(file,TextDocumentExport.Export("# Heading\n\nEnglish **bold** & 中文 😀.\n\nAnother paragraph.","Title",format));
   if(format=="docx")using(var zip=ZipFile.Open(file,ZipArchiveMode.Update)){var doc=XDocument.Parse(Read(zip,"word/document.xml"));doc.Root.Element(w+"body").AddFirst(new XElement(w+"tbl",new XElement(w+"tr",new XElement(w+"tc",new XElement(w+"p",new XElement(w+"r",new XElement(w+"t","Table text")))))));zip.GetEntry("word/document.xml").Delete();Write(zip,"word/document.xml",doc.ToString());Write(zip,"word/media/unchanged.dat","image fixture unchanged");}
   var source=TranslationDocuments.Prepare(file);Check(source.parts.Count>0&&source.parts.All(p=>p.Contains("<kok-r-"))&&String.Join("",source.displayParts).Contains("😀"),"Structured source extraction failed");
   var translations=source.parts.Select(TranslateMarkup).ToList();var indices=Enumerable.Range(0,translations.Count).ToList();
   foreach(bool bilingual in new[]{false,true}){string output=Path.Combine(root,(bilingual?"bilingual.":"translated.")+format);File.WriteAllBytes(output,TranslationDocuments.Export(file,source.signature,indices,translations,bilingual));var book=Library.ReadBook(new Entry{path=output,name="Translation",kind="document",ext=format.ToUpperInvariant()});Check(String.Join("",book.chapters.Select(c=>c.text)).Contains("译文"),"Translated "+format+" does not reopen");using(var zip=ZipFile.OpenRead(output)){if(format=="docx"){var doc=XDocument.Parse(Read(zip,"word/document.xml"));Check(doc.Descendants(w+"b").Any()&&doc.Descendants(w+"tbl").Any()&&Read(zip,"word/media/unchanged.dat")=="image fixture unchanged","DOCX styles, tables or assets changed");if(bilingual)Check(doc.Descendants(w+"tr").First().Elements(w+"tc").Count()==2,"DOCX bilingual columns missing");}else{Check(Read(zip,"mimetype")=="application/epub+zip","EPUB type changed");if(bilingual)Check(Read(zip,"OEBPS/content.xhtml").Contains("kok-bilingual"),"EPUB bilingual columns missing");}}}
   bool rejected=false;try{TranslationDocuments.Export(file,"wrong signature",indices,translations,false);}catch(InvalidDataException){rejected=true;}Check(rejected,"Changed source file was accepted");rejected=false;try{TranslationDocuments.Export(file,source.signature,indices,translations.Select(t=>"missing tags").ToList(),false);}catch(InvalidDataException){rejected=true;}Check(rejected,"Broken format tags accepted");
  }
  Console.WriteLine("PASS: structured DOCX/EPUB copies retain styles, tables, assets and bilingual columns; reopen and source validation.");
  var handler=new TranslateHandler();var service=new TranslationService(Path.Combine(root,"translations"),()=>handler);service.SaveConfig(new Dictionary<string,object>{{"endpoint","http://127.0.0.1:1234/v1"},{"model","mock"}});var parts=Enumerable.Range(0,24).Select(n=>n+" "+new string('x',1000)).ToList();int completed=0,batches=0;var result=await service.TranslateAsync(parts,CancellationToken.None,(n,total)=>{Check(n>=completed,"Progress moved backward");completed=n;},true,"简体中文",(start,values)=>batches++);Check(handler.maximum==3&&handler.calls==5&&result.parts[18]=="译文："+parts[18]&&completed==24&&batches==5,"Bounded concurrency/order/progressive output failed");
  var again=await service.TranslateAsync(parts,CancellationToken.None,(a,b)=>{},true,"简体中文");Check(again.cached&&handler.calls==5,"Full document cache failed");int before=handler.calls;var subset=await service.TranslateAsync(parts.Skip(4).Take(8).ToList(),CancellationToken.None,(a,b)=>{},true,"简体中文");Check(subset.cached&&handler.calls==before,"Cross-scope fragment cache failed");
  string resumeRoot=Path.Combine(root,"resume");var resumeHandler=new TranslateHandler();var resume=new TranslationService(resumeRoot,()=>resumeHandler);resume.SaveConfig(new Dictionary<string,object>{{"endpoint","http://127.0.0.1:1234/v1"},{"model","mock"}});using(var cancel=new CancellationTokenSource()){try{await resume.TranslateAsync(parts,cancel.Token,(a,b)=>{if(a>0)cancel.Cancel();});}catch(OperationCanceledException){}}Check(Directory.GetFiles(Path.Combine(resumeRoot,"translations"),"part-*.json").Length>0,"Cancellation did not preserve completed fragments");var freshHandler=new TranslateHandler();var resumed=new TranslationService(resumeRoot,()=>freshHandler);var resumedResult=await resumed.TranslateAsync(parts,CancellationToken.None,(a,b)=>{});Check(freshHandler.calls<5&&resumedResult.parts.Count==24,"Resuming repeated completed requests");
  bool malformed=false;handler.badTags=true;try{await service.TranslateAsync(new List<string>{"<kok-r-0>Hello</kok-r-0>"},CancellationToken.None,(a,b)=>{},false);}catch(InvalidDataException){malformed=true;}Check(malformed,"Invalid translated markup was cached or accepted");Console.WriteLine("PASS: three-worker translation, ordered progressive output, fragment reuse, cancellation/resume and format validation.");
  var speechHandler=new SpeechHandler();string speechRoot=Path.Combine(root,"speech");var speech=new SpeechService(speechRoot,()=>speechHandler);speech.Save(new Dictionary<string,object>{{"mode","api"},{"endpoint","http://127.0.0.1:1234/v1"},{"apiKey","dummy-asr-credential"}});Check(!File.ReadAllText(Path.Combine(speechRoot,"speech-settings.json")).Contains("dummy-asr-credential")&&!Library.Json.Serialize(speech.Public()).Contains("dummy-asr-credential"),"Speech key not protected");
  string encoder=args[1],probe=args[2],audio=args[3];var cloud=await speech.Generate(audio,encoder,probe,CancellationToken.None,p=>{});Check(cloud.cues.Count==2&&speechHandler.safe&&cloud.generated,"Timestamped cloud ASR request/parser failed");Check(!Directory.EnumerateFiles(Path.Combine(speechRoot,"speech-work"),"*",SearchOption.AllDirectories).Any(),"Speech temporary audio was retained");
  var parsed=SpeechService.ParseResponse("{\"segments\":[{\"start\":1,\"end\":2,\"text\":\"Offset\"}]}","verbose_json",480,5);Check(parsed[0].start==481&&parsed[0].end==482,"ASR chunk offset wrong");bool noTime=false;try{SpeechService.ParseResponse("{\"text\":\"No timestamps\"}","verbose_json",0,5);}catch(InvalidDataException){noTime=true;}Check(noTime,"Untimed response accepted as real captions");
  Console.WriteLine("PASS: real local audio extraction, timestamped ASR multipart upload to a mock, encrypted separate credentials and temp cleanup.");
  if(args.Length>5){speech.ChooseLocal(args[4],false);speech.ChooseLocal(args[5],true);speech.Save(new Dictionary<string,object>{{"mode","local"},{"language","en"}});var local=await speech.Generate(audio,encoder,probe,CancellationToken.None,p=>{});string transcript=String.Join(" ",local.cues.Select(c=>c.text));Check(local.cues.Count>0&&transcript.IndexOf("country",StringComparison.OrdinalIgnoreCase)>=0&&speechHandler.calls==1,"Real Whisper transcription failed or went online");Console.WriteLine("PASS: real official Whisper CPU inference creates timed captions without network requests.");}
 }
}
